34: #include <stdlib.h>
35: #include <string.h>
36: #ifdef HAVE_ICONV
37: #include "iconv.h"
38: #endif
39: #include "libmtp.h"
40: #include "unicode.h"
41: #include "util.h"
42: #include "ptp.h"
