44: /**
45:  * The size of the buffer (in characters) used for creating string copies.
46:  */
47: #define STRING_BUFFER_LENGTH 1024
48: 
49: /**
50:  * Gets the length (in characters, not bytes) of a unicode
51:  * UCS-2 string, eg a string which physically is 0x00 0x41 0x00 0x00
52:  * will return a value of 1.
53:  *
54:  * @param unicstr a UCS-2 Unicode string
55:  * @return the length of the string, in number of characters. If you
56:  *         want to know the length in bytes, multiply this by two and
57:  *         add two (for zero terminator).
58:  */
59: int ucs2_strlen(uint16_t const * const unicstr)
60: {
61:   int length;
62: 
63:   /* Unicode strings are terminated with 2 * 0x00 */
64:   for(length = 0; unicstr[length] != 0x0000U; length ++);
65:   return length;
66: }
67: 
68: /**
69:  * Converts a big-endian UTF-16 2-byte string
70:  * to a UTF-8 string. Actually just a UCS-2 internal conversion
71:  * routine that strips off the BOM if there is one.
72:  *
73:  * @param device a pointer to the current device.
74:  * @param unicstr the UTF-16 unicode string to convert
75:  * @return a UTF-8 string.
76:  */
77: char *utf16_to_utf8(LIBMTP_mtpdevice_t *device, const uint16_t *unicstr)
78: {
79:   char loclstr[STRING_BUFFER_LENGTH*3+1]; // UTF-8 encoding is max 3 bytes per UCS2 char.
80: 
81:   loclstr[0]='\0';
82:   #if defined(HAVE_ICONV) && defined(HAVE_LANGINFO_H)
83:   PTPParams *params = (PTPParams *) device->params;
84:   char *stringp = (char *) unicstr;
85:   char *locp = loclstr;
86:   size_t nconv;
87:   size_t convlen = (ucs2_strlen(unicstr)+1) * sizeof(uint16_t); // UCS-2 is 16 bit wide, include terminator
88:   size_t convmax = STRING_BUFFER_LENGTH*3;
89:   /* Do the conversion.  */
90:   nconv = iconv(params->cd_ucs2_to_locale, &stringp, &convlen, &locp, &convmax);
91:   if (nconv == (size_t) -1) {
92:     // Return partial string anyway.
93:     *locp = '\0';
94:   }
95:   #endif
96:   loclstr[STRING_BUFFER_LENGTH*3] = '\0';
97:   // Strip off any BOM, it's totally useless...
98:   if ((uint8_t) loclstr[0] == 0xEFU && (uint8_t) loclstr[1] == 0xBBU && (uint8_t) loclstr[2] == 0xBFU) {
99:     return strdup(loclstr+3);
100:   }
101:   return strdup(loclstr);
102: }
103: 
104: /**
105:  * Converts a UTF-8 string to a big-endian UTF-16 2-byte string
106:  * Actually just a UCS-2 internal conversion.
107:  *
108:  * @param device a pointer to the current device.
109:  * @param localstr the UTF-8 unicode string to convert
110:  * @return a UTF-16 string.
111:  */
112: uint16_t *utf8_to_utf16(LIBMTP_mtpdevice_t *device, const char *localstr)
113: {
114:   char unicstr[(STRING_BUFFER_LENGTH+1)*2]; // UCS2 encoding is 2 bytes per UTF-8 char.
115:   char *unip = unicstr;
116:   size_t nconv = 0;
117: 
118:   unicstr[0]='\0';
119:   unicstr[1]='\0';
120: 
121:   #if defined(HAVE_ICONV) && defined(HAVE_LANGINFO_H)
122:   PTPParams *params = (PTPParams *) device->params;
123:   char *stringp = (char *) localstr; // cast away "const"
124:   size_t convlen = strlen(localstr)+1; // utf8 bytes, include terminator
125:   size_t convmax = STRING_BUFFER_LENGTH*2;
126:   /* Do the conversion.  */
127:   nconv = iconv(params->cd_locale_to_ucs2, &stringp, &convlen, &unip, &convmax);
128:   #endif
129:   
130:   if (nconv == (size_t) -1) {
131:     // Return partial string anyway.
132:     unip[0] = '\0';
133:     unip[1] = '\0';
134:   }
135:   // make sure the string is null terminated
136:   unicstr[STRING_BUFFER_LENGTH*2] = '\0';
137:   unicstr[STRING_BUFFER_LENGTH*2+1] = '\0';
138: 
139:   // allocate the string to be returned
140:   // Note: can't use strdup since every other byte is a null byte
141:   int ret_len = ucs2_strlen((uint16_t*)unicstr)*sizeof(uint16_t)+2;
142:   uint16_t* ret = malloc(ret_len);
143:   memcpy(ret,unicstr,(size_t)ret_len);
144:   return ret;
145: }
146: 
147: /**
148:  * This helper function simply removes any consecutive chars
149:  * > 0x7F and replace then with an underscore. In UTF-8
150:  * consecutive chars > 0x7F represent one single character so
151:  * it has to be done like this (and it's elegant). It will only
152:  * shrink the string in size so no copying is needed.
153:  */
154: void strip_7bit_from_utf8(char *str)
155: {
156:   int i,j,k;
157:   i = 0;
158:   j = 0;
159:   k = strlen(str);
160:   while (i < k) {
161:     if ((uint8_t) str[i] > 0x7FU) {
162:       str[j] = '_';
163:       i++;
164:       // Skip over any consecutive > 0x7F chars.
165:       while((uint8_t) str[i] > 0x7FU) {
166: 	i++;
167:       }
168:     } else {
169:       str[j] = str[i];
170:       i++;
171:     }
172:     j++;
173:   }
174:   // Terminate stripped string...
175:   str[j] = '\0';
176: }

