964:         unsigned long usbwritten = 0;
965:         int xwritten;
966: 
967:         towrite = size - curwrite;
968:         if (towrite > CONTEXT_BLOCK_SIZE) {
969:             towrite = CONTEXT_BLOCK_SIZE;
